/**
 * Audio DSP helpers (CONTRAIL audio lane, GAME_FORGE W8).
 * Seeded noise banks, waveshaper curves, a code-generated reverb impulse,
 * envelope helpers and tiny node factories. No samples, no files: every buffer
 * is generated by code with Rng (never Math.random) and cached per context, so
 * AudioContext and OfflineAudioContext behave identically.
 */
import { Rng } from '../../core/rng';

export const clamp = (x: number, lo: number, hi: number): number => (x < lo ? lo : x > hi ? hi : x);
export const dbToGain = (db: number): number => Math.pow(10, db / 20);
export const gainToDb = (g: number): number => 20 * Math.log10(Math.max(1e-12, Math.abs(g)));
export const midiToHz = (m: number): number => 440 * Math.pow(2, (m - 69) / 12);
export function smoothstep(e0: number, e1: number, x: number): number {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

/** Smallest exponential-ramp target (exp ramps cannot reach 0). */
export const EPS = 1e-5;

// ------------------------------------------------------------------ noise bank
export interface NoiseBank {
  white: AudioBuffer;
  pink: AudioBuffer;
  brown: AudioBuffer;
  /** sparse decaying impulses (fire / debris crackle) */
  crackle: AudioBuffer;
}
const banks = new WeakMap<BaseAudioContext, NoiseBank>();

/** Remove DC and scale to a target RMS. */
function normalise(d: Float32Array, rmsTarget: number): void {
  let mean = 0;
  for (let i = 0; i < d.length; i++) mean += d[i];
  mean /= d.length;
  let p = 0;
  for (let i = 0; i < d.length; i++) {
    d[i] -= mean;
    p += d[i] * d[i];
  }
  const k = rmsTarget / Math.sqrt(p / d.length || 1e-12);
  for (let i = 0; i < d.length; i++) d[i] *= k;
}

export function noiseBank(ctx: BaseAudioContext): NoiseBank {
  const hit = banks.get(ctx);
  if (hit) return hit;
  const sr = ctx.sampleRate;
  const n = Math.floor(sr * 2);
  const rng = new Rng(0x6e6f6973);
  const white = new Float32Array(n);
  for (let i = 0; i < n; i++) white[i] = rng.signed();
  // pink (Paul Kellet), two passes so the loop point is continuous
  const pink = new Float32Array(n);
  {
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (let pass = 0; pass < 2; pass++)
      for (let i = 0; i < n; i++) {
        const w = white[i];
        b0 = 0.99886 * b0 + w * 0.0555179;
        b1 = 0.99332 * b1 + w * 0.0750759;
        b2 = 0.969 * b2 + w * 0.153852;
        b3 = 0.8665 * b3 + w * 0.3104856;
        b4 = 0.55 * b4 + w * 0.5329522;
        b5 = -0.7616 * b5 - w * 0.016898;
        if (pass === 1) pink[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362;
        b6 = w * 0.115926;
      }
  }
  // brown: leaky integrator, two passes
  const brown = new Float32Array(n);
  {
    let b = 0;
    for (let pass = 0; pass < 2; pass++)
      for (let i = 0; i < n; i++) {
        b = 0.985 * b + 0.15 * white[i];
        if (pass === 1) brown[i] = b;
      }
  }
  // crackle: Poisson-spaced short decaying bursts
  const crackle = new Float32Array(n);
  {
    const r = new Rng(0x63726b6c);
    let t = 0;
    for (;;) {
      t += -Math.log(1 - r.next()) * (sr / 180);
      const i0 = Math.floor(t);
      if (i0 >= n) break;
      const len = r.int(6, 40);
      const a = r.range(0.2, 1) * (r.chance(0.5) ? 1 : -1);
      for (let k = 0; k < len && i0 + k < n; k++) crackle[i0 + k] += a * Math.exp(-k / (len * 0.3)) * r.signed();
    }
  }
  normalise(white, 0.3);
  normalise(pink, 0.3);
  normalise(brown, 0.3);
  normalise(crackle, 0.3);
  const mk = (d: Float32Array<ArrayBuffer>): AudioBuffer => {
    const b = ctx.createBuffer(1, n, sr);
    b.copyToChannel(d, 0);
    return b;
  };
  const bank: NoiseBank = { white: mk(white), pink: mk(pink), brown: mk(brown), crackle: mk(crackle) };
  banks.set(ctx, bank);
  return bank;
}

// ------------------------------------------------------------------ reverb IR
const irCache = new WeakMap<BaseAudioContext, Map<string, AudioBuffer>>();

/** Stereo, decorrelated, exponentially decaying noise impulse that darkens over time. */
export function reverbImpulse(ctx: BaseAudioContext, seconds = 1.6, rt60 = 1.3, seed = 7, brightness = 0.55): AudioBuffer {
  let m = irCache.get(ctx);
  if (!m) irCache.set(ctx, (m = new Map()));
  const key = `${seconds}|${rt60}|${seed}|${brightness}`;
  const hit = m.get(key);
  if (hit) return hit;
  const sr = ctx.sampleRate;
  const n = Math.floor(seconds * sr);
  const buf = ctx.createBuffer(2, n, sr);
  for (let ch = 0; ch < 2; ch++) {
    const r = new Rng(seed * 31 + ch * 7919);
    const d = new Float32Array(n);
    let lp = 0;
    for (let i = 0; i < n; i++) {
      const t = i / sr;
      const env = Math.pow(10, (-3 * t) / rt60);
      const a = brightness * (1 - 0.8 * (t / seconds)) + 0.04;
      lp += a * (r.signed() - lp);
      d[i] = lp * env;
    }
    for (let k = 0; k < 6; k++) {
      const i = Math.floor(sr * r.range(0.006, 0.05));
      d[i] += r.range(0.08, 0.2) * (r.chance(0.5) ? 1 : -1);
    }
    const fin = Math.floor(sr * 0.002), fout = Math.floor(sr * 0.08);
    for (let i = 0; i < fin; i++) d[i] *= i / fin;
    for (let i = 0; i < fout; i++) d[n - 1 - i] *= i / fout;
    buf.copyToChannel(d, ch);
  }
  m.set(key, buf);
  return buf;
}

// ------------------------------------------------------------------ curves
const curveCache = new Map<string, Float32Array<ArrayBuffer>>();

/** Symmetric tanh saturation curve normalised to +-1 (odd length: exact 0 -> no DC). */
export function driveCurve(drive: number): Float32Array<ArrayBuffer> {
  const key = `d${drive}`;
  let c = curveCache.get(key);
  if (!c) {
    const n = 2049;
    c = new Float32Array(n);
    const k = Math.tanh(drive);
    for (let i = 0; i < n; i++) {
      const x = (i / (n - 1)) * 2 - 1;
      c[i] = Math.tanh(drive * x) / k;
    }
    curveCache.set(key, c);
  }
  return c;
}

/** Master ceiling: identity below `knee`, tanh approach to `ceiling` above. Inputs beyond +-1 clamp to the ends. */
export function ceilingCurve(knee: number, ceiling: number): Float32Array<ArrayBuffer> {
  const key = `c${knee}|${ceiling}`;
  let c = curveCache.get(key);
  if (!c) {
    const n = 8193;
    c = new Float32Array(n);
    const span = ceiling - knee;
    for (let i = 0; i < n; i++) {
      const x = (i / (n - 1)) * 2 - 1;
      const ax = Math.abs(x);
      const y = ax <= knee ? ax : knee + span * Math.tanh((ax - knee) / span);
      c[i] = x < 0 ? -y : y;
    }
    curveCache.set(key, c);
  }
  return c;
}

// ------------------------------------------------------------------ node helpers
export function safeHz(ctx: BaseAudioContext, hz: number): number {
  return clamp(hz, 5, ctx.sampleRate * 0.45);
}

export function tone(ctx: BaseAudioContext, type: OscillatorType, hz: number, t0: number, t1: number, detune = 0): OscillatorNode {
  const o = ctx.createOscillator();
  o.type = type;
  o.frequency.setValueAtTime(safeHz(ctx, hz), t0);
  if (detune) o.detune.setValueAtTime(detune, t0);
  o.start(t0);
  o.stop(t1);
  return o;
}

export function noise(ctx: BaseAudioContext, buf: AudioBuffer, t0: number, t1: number, rng: Rng, rate = 1): AudioBufferSourceNode {
  const s = ctx.createBufferSource();
  s.buffer = buf;
  s.loop = true;
  s.playbackRate.setValueAtTime(rate, t0);
  s.start(t0, rng.range(0, buf.duration * 0.9));
  s.stop(t1);
  return s;
}

export function filt(ctx: BaseAudioContext, type: BiquadFilterType, hz: number, q = 0.707, gainDb = 0): BiquadFilterNode {
  const f = ctx.createBiquadFilter();
  f.type = type;
  f.frequency.value = safeHz(ctx, hz);
  f.Q.value = q;
  if (gainDb) f.gain.value = gainDb;
  // k-rate: coefficients per 128-sample block instead of per sample (sweeps stay smooth, ~3 ms steps)
  f.frequency.automationRate = 'k-rate';
  f.Q.automationRate = 'k-rate';
  f.gain.automationRate = 'k-rate';
  f.detune.automationRate = 'k-rate';
  return f;
}

export function amp(ctx: BaseAudioContext, v = 0): GainNode {
  const g = ctx.createGain();
  g.gain.value = v;
  return g;
}

export function shaper(ctx: BaseAudioContext, curve: Float32Array<ArrayBuffer>, oversample: OverSampleType = '2x'): WaveShaperNode {
  const w = ctx.createWaveShaper();
  w.curve = curve;
  w.oversample = oversample;
  return w;
}

export function chain(...nodes: AudioNode[]): void {
  for (let i = 0; i < nodes.length - 1; i++) nodes[i].connect(nodes[i + 1]);
}

/** Attack (linear) then exponential decay to -60 dB over `decay`, then 0. Returns end time. */
export function envAD(p: AudioParam, t0: number, attack: number, decay: number, peak: number): number {
  const pk = Math.max(EPS * 10, peak);
  p.setValueAtTime(0, t0);
  p.linearRampToValueAtTime(pk, t0 + attack);
  p.exponentialRampToValueAtTime(Math.max(EPS, pk * 1e-3), t0 + attack + decay);
  p.linearRampToValueAtTime(0, t0 + attack + decay + 0.006);
  return t0 + attack + decay + 0.006;
}

/** Attack, hold until holdEnd, linear release. Returns end time. */
export function envASR(p: AudioParam, t0: number, attack: number, holdEnd: number, release: number, peak: number): number {
  p.setValueAtTime(0, t0);
  p.linearRampToValueAtTime(peak, t0 + attack);
  p.setValueAtTime(peak, Math.max(t0 + attack, holdEnd));
  p.linearRampToValueAtTime(0, Math.max(t0 + attack, holdEnd) + release);
  return Math.max(t0 + attack, holdEnd) + release;
}

/** Glide a parameter (exponential when both ends are positive). */
export function glide(p: AudioParam, from: number, to: number, t0: number, t1: number, exp = true): void {
  p.setValueAtTime(from, t0);
  if (exp && from > 0 && to > 0) p.exponentialRampToValueAtTime(to, t1);
  else p.linearRampToValueAtTime(to, t1);
}

/** Hold the current automated value at `at` (cancelAndHoldAtTime with a fallback). */
export function holdAt(p: AudioParam, at: number, fallback: number): void {
  const anyP = p as AudioParam & { cancelAndHoldAtTime?: (t: number) => AudioParam };
  if (typeof anyP.cancelAndHoldAtTime === 'function') anyP.cancelAndHoldAtTime(at);
  else {
    p.cancelScheduledValues(at);
    p.setValueAtTime(fallback, at);
  }
}
